# -*- coding: utf-8 -*-
# Сверка с ответами учебника Мерзляк 10, часть 3 (расхождения 110–149): пересчитано вручную + SymPy (check_mz3.py), условия сверены со сканом.
KB = "ключ неверен (сверка с ответом учебника Мерзляк 10 и пересчёт вручную): "
SRC = "сверка с ответами учебника Мерзляк 10 (углублённый) 25.09 + пересчёт вручную"
P = {}
def K(t, k, note, **kw):
    P[t] = {"k": k, "why": KB + note, "src": SRC}; P[t].update(kw)
K("G10_TB_§30_30_6_5", r"$x = 7\pi + 12\pi n$; $x = -\pi + 12\pi n$", "sin(x/6) = −1/2 ⇒ x = (−1)^{n+1}π + 6πn, т. е. −π + 12πn и 7π + 12πn; x = 3π не корень: sin(π/2) = 1 (было 3π + 12πn)")
K("G10_TB_§39_39_11_2", r"Возрастает на $(-\infty; -4)$ и $(0; +\infty)$, убывает на $(-4; 0)$; $x_{\max}=-4$, $x_{\min}=0$", "f′ = 7x(x + 4)³(x − 3)²: знак меняется в −4 (+/−) и 0 (−/+), в 3 не меняется (было: максимум 0, минимум 3)")
K("G10_TB_§39_39_10_2", r"Возрастает на $(-\infty; 1{,}6)$ и $(2; +\infty)$, убывает на $(1{,}6; 2)$; $x_{\max}=1{,}6$, $x_{\min}=2$", "f′ = (x − 1)²(x − 2)(5x − 8): в 1 знак не меняется, максимум 1,6, минимум 2 (было: максимум 1, минимум 1,6)")
K("G10_TB_§40_40_4_4", r"Наибольшее значение: $10$, наименьшее значение: $6$", "f(−6) = 7,5, f(−3) = 6, f(−1) = 10 (было: наибольшее 6, наименьшее 7,5)")
K("G10_TB_§37_37_2_6", r"$y = 5x - 18$", "f(3) = −3, f′ = (x² − 4x + 8)/(x − 2)², f′(3) = 5 ⇒ y = 5x − 18 (было y = x − 6)")
K("G10_TB_§30_30_6_9", r"$x = \pi n$; $x = \dfrac{\pi}{6} + \pi n$, $n \in \mathbb{Z}$", "3/cos²x = 3 + 3tg²x ⇒ tg x(3tg x − √3) = 0 ⇒ tg x = 0 или tg x = √3/3 (было π/3 + πn)")
K("G10_TB_§35_35_23_3", r"$-3$; $3$", "−3/x⁴ = −1/27 ⇒ x⁴ = 81 ⇒ x = ±3 (был только корень 3)")
K("G10_TB_§27_27_11", r"$-\dfrac{5\pi}{6}; \dfrac{\pi}{2}; \dfrac{7\pi}{6}$", "x = π/2 + 2πk или 7π/6 + 2πk; на [−π; 3π/2]: −5π/6, π/2, 7π/6; −π/6 не корень: sin(−π/2) = −1 (было −π/6)")
P["G10_TB_§31_31_7_9"] = {"q": r"Решите уравнение: $\cos 9x = 2 \sin\left(\dfrac{3\pi}{2} - 3x\right)$", "k": r"$x = \dfrac{\pi}{6} + \dfrac{\pi k}{3}$; $x = \pm\dfrac{\pi}{9} + \dfrac{\pi k}{3}$", "src": SRC,
  "why": KB + "cos 9x = 4cos³3x − 3cos 3x = −2cos 3x ⇒ cos 3x(4cos²3x − 1) = 0 ⇒ x = π/6 + πk/3 или cos 6x = −1/2 ⇒ x = ±π/9 + πk/3; x = π/12 не корень (было π/12 + πk/3); запись «3 · π/2» в условии заменена на 3π/2, как в учебнике"}
K("G10_TB_§26_26_10", r"$\dfrac{7\pi}{12}$; $\dfrac{5\pi}{4}$; $\dfrac{31\pi}{12}$; $\dfrac{13\pi}{4}$", "нужны корни из (−π/6; 4π), а не серии: x = 7π/12 + 2πk или −3π/4 + 2πk ⇒ 7π/12, 5π/4, 31π/12, 13π/4 (ключ был записан сериями)")
K("G10_TB_§36_36_19_1", r"$\dfrac{9}{x^{4}} - \dfrac{9}{x^{10}}$", "(x⁻⁹ − 3x⁻³)′ = −9x⁻¹⁰ + 9x⁻⁴ (ключ был искажён: (−9/x)¹⁰ + (9/x)⁴)")
K("G10_TB_§39_39_10_3", r"Возрастает на $(0; +\infty)$, убывает на $(-\infty; 0)$; $x_{\min} = 0$", "f′ = x³(x + 2)²: в −2 знак не меняется, единственный экстремум — минимум 0 (было: минимум −2, максимум 0)")
K("G10_TB_§39_39_10_1", r"Возрастает на $(6; +\infty)$, убывает на $(-\infty; 6)$; $x_{\min} = 6$", "f′ = x²(x − 6): в 0 знак не меняется, минимум 6 (было: минимум 0, максимум 6)")
